// Weekly reports use the end date of saved sessions, as the annual report does.
function weekRange(value){
  var d=new Date((value||localDateKey(new Date()))+'T12:00:00');
  if(isNaN(d.getTime()))d=new Date();
  d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));
  var days=[];for(var i=0;i<8;i++){var date=new Date(d);date.setDate(d.getDate()+i);days.push(date)}
  var thursday=new Date(days[3]),year=thursday.getFullYear();
  var dayNumber=Math.round((Date.UTC(year,thursday.getMonth(),thursday.getDate())-Date.UTC(year,0,1))/86400000);
  return {start:days[0].getTime()/1000,end:days[7].getTime()/1000,days:days,number:Math.floor(dayNumber/7)+1,year:year};
}
function weeklyData(range){
  var tasks=new Map(),projects=new Map(),rows=new Map(),days=[0,0,0,0,0,0,0],total=0,filtered=0;
  state.tasks.concat(state.archivedTasks,state.projectArchivedTasks).forEach(function(t){tasks.set(String(t.id),t)});
  state.projects.concat(state.archivedProjects).forEach(function(p){projects.set(String(p.id),p)});
  state.time.forEach(function(e){
    var seconds=Number(e.Duration),end=Number(e.End_Time);
    if(!end||end<range.start||end>=range.end||!Number.isFinite(seconds)||seconds<=0)return;
    total+=seconds;
    var task=tasks.get(String(e.Task_Id)),project=task&&projects.get(String(task.Project_Id));
    if(state.project&&(!task||String(task.Project_Id)!==String(state.project)))return;
    var index=range.days.findIndex(function(date,i){return i<7&&end>=date.getTime()/1000&&end<range.days[i+1].getTime()/1000});
    if(index<0)return;
    filtered+=seconds;days[index]+=seconds;
    var key=String(e.Task_Id),row=rows.get(key);
    if(!row){row={task:task,title:task?task.Title:'Tâche indisponible (réf. '+key+')',project:project?project.Name:task&&!task.Project_Id?'Sans projet':'Projet indisponible',archived:!!(task&&(task.Archived_At||(project&&project.Archived_At))),days:[0,0,0,0,0,0,0],total:0};rows.set(key,row)}
    row.days[index]+=seconds;row.total+=seconds;
  });
  return {total:total,filtered:filtered,days:days,rows:Array.from(rows.values()).sort(function(a,b){return b.total-a.total||String(a.title).localeCompare(String(b.title))})};
}
function weeklyTarget(range){var value=state.weekTargets[localDateKey(range.days[0])];return typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=168*3600?value:39*3600}
function loadWeekTargets(settings){state.weekTargets={};settings.forEach(function(s){if(/^weekly_target_\d{4}-\d{2}-\d{2}$/.test(s.Key)&&s.Value!==''&&s.Value!=null){var n=Number(s.Value);if(Number.isFinite(n)&&n>=0&&n<=168*3600)state.weekTargets[s.Key.slice(14)]=n}})}
var weekTargetSaving=false;
async function saveWeekTarget(){
  if(weekTargetSaving)return;
  var h=Number($('week-target-hours').value),m=Number($('week-target-minutes').value),seconds=h*3600+m*60,date=localDateKey(weekRange(state.reportWeek).days[0]);
  if($('week-target-hours').value===''||!Number.isInteger(h)||!Number.isInteger(m)||h<0||m<0||m>59||seconds>168*3600){toast('Indiquez un objectif valide en heures et minutes');return}
  weekTargetSaving=true;$('save-week-target').disabled=true;
  try{if(state.demo){state.weekTargets[date]=seconds;demoSave()}else{var data=await grist.docApi.fetchTable(TABLES.settings),key='weekly_target_'+date,record=records(data,settingMap()).find(function(s){return s.Key===key});await grist.docApi.applyUserActions([record?['UpdateRecord',TABLES.settings,Number(record.id),{Value:String(seconds)}]:['AddRecord',TABLES.settings,null,{Key:key,Value:String(seconds)}]]);state.weekTargets[date]=seconds}renderReport();toast('Objectif enregistré pour la semaine du '+fmtDate(unix(date)))}catch(e){toast('Impossible d’enregistrer l’objectif : '+e.message)}finally{weekTargetSaving=false;$('save-week-target').disabled=false}
}
function renderWeeklyReport(){
  var r=weekRange(state.reportWeek),data=weeklyData(r),target=weeklyTarget(r),difference=data.total-target;
  state.reportWeek=localDateKey(r.days[0]);$('report-week-date').value=state.reportWeek;
  var label='Semaine '+r.number+' · '+fmtDate(r.start)+' au '+fmtDate(r.days[6].getTime()/1000);
  $('report-year').textContent=label;
  $('week-target-hours').value=Math.floor(target/3600);$('week-target-minutes').value=Math.floor(target%3600/60);
  $('weekly-scope').textContent=state.project?'Détail du projet : '+projectName(state.project)+'. L’objectif hebdomadaire porte sur tous les projets.':'Tous les projets et tâches autonomes, y compris les archives.';
  $('weekly-metrics').innerHTML=metric('Total de la semaine',duration(data.total),'Tous projets, archives comprises')+metric('Objectif de la semaine',duration(target),target===39*3600?'Cycle habituel de 39 h':'Objectif adapté pour cette semaine')+metric(difference<0?'Écart sous l’objectif':difference>0?'Au-dessus de l’objectif':'Objectif atteint',duration(Math.abs(difference)),difference<0?'Heures non couvertes par les saisies':'Par rapport à l’objectif de la semaine')+metric('Temps du périmètre affiché',duration(data.filtered),state.project?projectName(state.project):'Tous les projets');
  $('weekly-progress').max=target||1;$('weekly-progress').value=Math.min(data.total,target);$('weekly-progress').classList.toggle('hidden',target===0);
  $('weekly-progress-label').textContent=duration(data.total)+' enregistrées · objectif '+duration(target)+(target?' · '+Math.round(data.total/target*100)+' %':' · aucun temps de travail prévu');
  $('weekly-running').classList.toggle('hidden',!activeEntry());
  $('weekly-days').innerHTML=barList(data.days.map(function(seconds,i){return {label:r.days[i].toLocaleDateString('fr-FR',{weekday:'short',day:'2-digit',month:'2-digit'}),value:seconds,display:duration(seconds)}}));
  $('weekly-details').innerHTML=data.rows.length?'<table class="report-table weekly-table"><thead><tr><th scope="col">Tâche / projet</th>'+r.days.slice(0,7).map(function(d){return '<th scope="col">'+esc(d.toLocaleDateString('fr-FR',{weekday:'short',day:'2-digit',month:'2-digit'}))+'</th>'}).join('')+'<th scope="col">Total</th></tr></thead><tbody>'+data.rows.map(function(row){var title=esc(row.title);if(row.task&&!row.archived)title='<button type="button" class="task-report-link" onclick="openTask('+Number(row.task.id)+')">'+title+'</button>';return '<tr><th scope="row">'+title+'<div class="sub">'+esc(row.project)+(row.archived?' · Archivée':'')+'</div></th>'+row.days.map(function(s){return '<td>'+ (s?duration(s):'—')+'</td>'}).join('')+'<td><strong>'+duration(row.total)+'</strong></td></tr>'}).join('')+'</tbody><tfoot><tr><th scope="row">Total affiché</th>'+data.days.map(function(s){return '<td>'+duration(s)+'</td>'}).join('')+'<td>'+duration(data.filtered)+'</td></tr></tfoot></table>':'<div class="empty">Aucun temps enregistré pour cette semaine dans le périmètre affiché.</div>';
}
function moveReportWeek(offset){var r=weekRange(state.reportWeek),d=r.days[0];d.setDate(d.getDate()+offset*7);state.reportWeek=localDateKey(d);renderReport()}
function kanbanClosedDate(task){return Number(task.Completed_At)||(task.Status==='cancelled'?Number(task.Updated_At):0)||0}
function kanbanLaneTasks(tasks,status){
  var list=tasks.filter(function(t){return t.Status===status});
  if(!isDone(status))return {all:list,matching:list,visible:list};
  var cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-(Number(state.kanbanClosedPeriod)||30)+1);
  var matching=list.filter(function(t){return state.kanbanClosedPeriod==='all'||kanbanClosedDate(t)>=cutoff.getTime()/1000}).sort(function(a,b){return kanbanClosedDate(b)-kanbanClosedDate(a)||Number(b.id)-Number(a.id)});
  return {all:list,matching:matching,visible:matching.slice(0,state.kanbanClosedLimit[status]||20)};
}
function showMoreClosed(status){state.kanbanClosedLimit[status]=(state.kanbanClosedLimit[status]||20)+20;renderKanban()}

function reportTasks(){return state.tasks.filter(function(t){return !state.project||String(t.Project_Id)===String(state.project)})}
function barList(items){var max=Math.max.apply(null,items.map(function(x){return x.value}).concat([1]));return items.length?'<div class="bar-list">'+items.map(function(x){return '<div class="bar-row"><span>'+esc(x.label)+'</span><div class="bar-track"><div class="bar-fill" style="width:'+(x.value/max*100)+'%"></div></div><strong>'+esc(x.display)+'</strong></div>'}).join('')+'</div>':'<div class="empty">Aucune donnée enregistrée.</div>'}
function reportRange(){var y=state.year,p=state.reportPeriod,map={year:[0,12],h1:[0,6],h2:[6,12],q1:[0,3],q2:[3,6],q3:[6,9],q4:[9,12]},x=map[p]||map.year;return {start:new Date(y,x[0],1).getTime()/1000,end:new Date(y,x[1],1).getTime()/1000,months:[x[0],x[1]]}}
function timeInRange(taskId,r){return state.time.filter(function(e){return String(e.Task_Id)===String(taskId)&&e.End_Time>=r.start&&e.End_Time<r.end}).reduce(function(s,e){return s+(Number(e.Duration)||0)},0)}
