function projectPeriod(p){if(p.Start_Date&&p.Due_Date)return fmtDate(p.Start_Date)+' → '+fmtDate(p.Due_Date);if(p.Due_Date)return 'Échéance : '+fmtDate(p.Due_Date);if(p.Start_Date)return 'Démarré le '+fmtDate(p.Start_Date);return 'Période non renseignée'}
// Aggregated resources are a read-only view over the existing Grist records.
var resourceProjectId=null;
function projectResources(projectId){
  var tasks=new Map();
  state.tasks.concat(state.archivedTasks,state.projectArchivedTasks).forEach(function(t){if(String(t.Project_Id)===String(projectId))tasks.set(String(t.id),t)});
  var rows=[];
  [['file',state.files],['link',state.links]].forEach(function(pair){pair[1].forEach(function(item){
    var task=item.Parent_Type==='task'?tasks.get(String(item.Parent_Id)):null;
    if(!(item.Parent_Type==='project'&&String(item.Parent_Id)===String(projectId))&&!task)return;
    rows.push({kind:pair[0],item:item,source:task?'Tâche : '+task.Title+(task.Archived_At?' (archivée)':isDone(task.Status)?' (terminée / annulée)':''):'Projet',title:pair[0]==='file'?item.File_Name:item.Label||item.URL});
  })});
  return rows.sort(function(a,b){return String(a.title||'').localeCompare(String(b.title||''),'fr')});
}
