function toggleReviewTasks(id,button){var box=$('review-tasks-'+id),opening=box.classList.contains('hidden');box.classList.toggle('hidden',!opening);button.textContent=opening?'Masquer les tâches':'Voir les tâches ouvertes ('+box.children.length+')'}
function projectPickerMatches(p,q){return !q||String(p.Name).toLowerCase().includes(q)||String(p.Type||'').toLowerCase().includes(q)}
function renderReviewPicker(){var q=($('review-search').value||'').trim().toLowerCase(),ps=state.projects.slice().sort(function(a,b){return Number(b.Review)-Number(a.Review)||a.Name.localeCompare(b.Name)}).filter(function(p){return projectPickerMatches(p,q)});$('review-count').textContent=state.projects.filter(function(p){return p.Review}).length+' projet(s) sélectionné(s)';$('review-picker').innerHTML=ps.length?ps.map(function(p){return '<label class="review-choice"><input type="checkbox" '+(p.Review?'checked':'')+' onchange="toggleProjectReview('+p.id+',this.checked)"><span><strong>'+esc(p.Name)+'</strong><br><small>'+esc(p.Type||'Projet')+' · '+esc(PROJECT_STATUSES[p.Status]||p.Status||'')+'</small></span></label>'}).join(''):'<div class="empty">Aucun projet trouvé.</div>'}
async function toggleProjectReview(id,checked){await updateRecord(TABLES.projects,id,{Review:checked,Updated_At:now()});var p=state.projects.find(function(x){return String(x.id)===String(id)});if(p)p.Review=checked;renderReviewPicker();renderReview();renderDashboard()}
function renderReportPicker(){var q=($('report-search').value||'').trim().toLowerCase(),ps=state.projects.slice().sort(function(a,b){return Number(b.Highlight)-Number(a.Highlight)||a.Name.localeCompare(b.Name)}).filter(function(p){return projectPickerMatches(p,q)});$('report-count').textContent=state.projects.filter(function(p){return p.Highlight}).length+' projet(s) sélectionné(s)';$('report-picker').innerHTML=ps.length?ps.map(function(p){return '<label class="review-choice"><input type="checkbox" '+(p.Highlight?'checked':'')+' onchange="toggleProjectHighlight('+p.id+',this.checked)"><span><strong>'+esc(p.Name)+'</strong><br><small>'+esc(p.Type||'Projet')+' · '+esc(PROJECT_STATUSES[p.Status]||p.Status||'')+'</small></span></label>'}).join(''):'<div class="empty">Aucun projet trouvé.</div>'}
