function renderGlobalSearch(){var q=normKey($('global-search').value),box=$('global-search-results');if(q.length<2){box.innerHTML='<div class="empty">Saisissez au moins deux caractères pour lancer la recherche.</div>';return}var results=[];function add(kind,title,snippet,type,id){results.push({kind:kind,title:title,snippet:snippet||'',type:type,id:id})}state.projects.forEach(function(p){var text=[p.Name,p.Type,p.Risks,p.Decision].join(' ');if(normKey(text).indexOf(q)!==-1)add('Projet',p.Name,[p.Type,PROJECT_STATUSES[p.Status]].filter(Boolean).join(' · '),'project',p.id)});state.tasks.forEach(function(t){var text=[t.Title,t.Notes,projectName(t.Project_Id)].join(' ');if(normKey(text).indexOf(q)!==-1)add('Tâche',t.Title,projectName(t.Project_Id)+' · '+statusLabel(t.Status),'task',t.id)});state.journal.forEach(function(x){if(searchParentActive(x.Parent_Type,x.Parent_Id)&&normKey(x.Content).indexOf(q)!==-1)add('Note du journal',searchParentTitle(x.Parent_Type,x.Parent_Id),x.Content,x.Parent_Type,x.Parent_Id)});state.files.forEach(function(x){if(searchParentActive(x.Parent_Type,x.Parent_Id)&&normKey(x.File_Name).indexOf(q)!==-1)add('Document',x.File_Name,'Rattaché à '+searchParentTitle(x.Parent_Type,x.Parent_Id),x.Parent_Type,x.Parent_Id)});state.links.forEach(function(x){if(searchParentActive(x.Parent_Type,x.Parent_Id)&&normKey([x.Label,x.URL,x.Notes].join(' ')).indexOf(q)!==-1)add('Lien',x.Label||x.URL,x.URL,x.Parent_Type,x.Parent_Id)});results=results.slice(0,60);box.innerHTML=results.length?results.map(function(r){var snippet=String(r.snippet).slice(0,180)+(String(r.snippet).length>180?'…':'');return '<div class="search-result"><div><span class="search-kind">'+esc(r.kind)+'</span><div class="list-title">'+esc(r.title)+'</div><div class="search-snippet">'+esc(snippet)+'</div></div><button class="btn small primary" onclick="openSearchResult(\''+r.type+'\','+r.id+')">Ouvrir</button></div>'}).join(''):'<div class="empty">Aucun résultat.</div>'}
