function renderTrash(){
  var projects=state.archivedProjects.slice().sort(function(a,b){return (b.Archived_At||0)-(a.Archived_At||0)});
  var tasks=state.archivedTasks.slice().sort(function(a,b){return (b.Archived_At||0)-(a.Archived_At||0)});
  function section(title,items,type){
    if(!items.length)return '<h4>'+title+' (0)</h4><div class="empty">Aucun élément.</div>';
    var rows=items.map(function(x){
      var name=type==='project'?x.Name:x.Title;
      var childCount=state.projectArchivedTasks.concat(state.archivedTasks).filter(function(t){return String(t.Project_Id)===String(x.id)}).length;
      var extra=type==='project'?childCount+' tâche(s) conservée(s)':esc(projectName(x.Project_Id));
      return '<div class="detail-row"><div><div class="list-title">'+esc(name)+'</div><div class="sub">Archivé le '+fmtDate(x.Archived_At)+' · '+extra+'</div></div><button class="btn small" onclick="restoreArchived(\''+type+'\','+x.id+')">Restaurer</button><button class="btn small danger" onclick="deleteArchived(\''+type+'\','+x.id+')">Supprimer définitivement</button></div>';
    }).join('');
    return '<h4>'+title+' ('+items.length+')</h4><div class="detail-list">'+rows+'</div>';
  }
  $('trash-body').innerHTML=section('Projets',projects,'project')+'<div style="height:18px"></div>'+section('Tâches',tasks,'task');
}
async function archiveItem(type,id){var table=type==='project'?TABLES.projects:TABLES.tasks,item=(type==='project'?state.projects:state.tasks).find(function(x){return String(x.id)===String(id)});if(!item)return;var running=activeEntry(),runningTask=running&&state.tasks.find(function(t){return String(t.id)===String(running.Task_Id)});if(running&&(type==='task'&&String(running.Task_Id)===String(id)||type==='project'&&runningTask&&String(runningTask.Project_Id)===String(id))){toast('Arrêtez le chronomètre avant d’archiver cet élément.');return}var detail=type==='project'?' Le projet et ses tâches resteront restaurables.':' Ses temps, documents et notes seront conservés.';if(!confirm('Archiver « '+(item.Name||item.Title)+' » ?'+detail))return;await updateRecord(table,id,{Archived_At:now(),Updated_At:now()});closeModal(type+'-modal',true);if(String(state.project)===String(id)&&type==='project')state.project='';await loadData();toast(type==='project'?'Projet placé dans la corbeille':'Tâche placée dans la corbeille')}
