function renderRelated(type,id){var box=$(type+'-related');box.classList.toggle('hidden',!id);if(!id)return;var files=relatedItems(state.files,type,id),links=relatedItems(state.links,type,id),journal=relatedItems(state.journal,type,id).sort(function(a,b){return (b.Created_At||0)-(a.Created_At||0)});$(type+'-files').innerHTML=files.length?files.map(function(x){return '<div class="related-item"><span>📎 <strong>'+esc(x.File_Name)+'</strong><br><small>'+formatFileSize(x.File_Size)+'</small></span><button type="button" class="btn small primary" onclick="viewFile('+x.id+')">Voir</button><button type="button" class="btn small danger" onclick="deleteRelated(\'files\','+x.id+',\''+type+'\')">×</button></div>'}).join(''):'<div class="sub">Aucun document.</div>';$(type+'-links').innerHTML=links.length?links.map(function(x){return '<div class="related-item"><a href="'+esc(x.URL)+'" target="_blank" rel="noopener noreferrer"><strong>🔗 '+esc(x.Label||x.URL)+'</strong></a><button type="button" class="btn small danger" onclick="deleteRelated(\'links\','+x.id+',\''+type+'\')">×</button></div>'}).join(''):'<div class="sub">Aucun lien.</div>';$(type+'-journal').innerHTML=journal.length?journal.map(function(x){return '<div class="related-item"><span><span class="journal-date">'+new Date(x.Created_At*1000).toLocaleString('fr-FR')+'</span><br>'+esc(x.Content)+'</span><button type="button" class="btn small danger" onclick="deleteRelated(\'journal\','+x.id+',\''+type+'\')">×</button></div>'}).join(''):'<div class="sub">Aucune note datée.</div>';if(type==='task'){var checks=state.checklist.filter(function(x){return String(x.Task_Id)===String(id)}).sort(function(a,b){return Number(a.Done)-Number(b.Done)||(a.Created_At||0)-(b.Created_At||0)});$('task-checklist').innerHTML=checks.length?checks.map(function(x){return '<div class="related-item check-item '+(x.Done?'done':'')+'"><input type="checkbox" '+(x.Done?'checked':'')+' onchange="toggleChecklist('+x.id+',this.checked)"><span class="check-text">'+esc(x.Text)+(x.Completed_At?'<br><small>Terminée le '+new Date(x.Completed_At*1000).toLocaleDateString('fr-FR')+'</small>':'')+'</span><button type="button" class="btn small danger" onclick="deleteRelated(\'checklist\','+x.id+',\'task\')">×</button></div>'}).join(''):'<div class="sub">Aucune mini-action.</div>'}}
async function addChecklistItem(){var id=relatedId('task'),text=$('task-check-text').value.trim();if(!id||!text)return;if(state.demo){toast('Disponible dans Grist.');return}await addRecord(TABLES.checklist,{Task_Id:id,Text:text,Done:false,Created_At:now(),Completed_At:null});$('task-check-text').value='';await loadData();renderRelated('task',id)}
