async function addExternalLink(type){var id=relatedId(type),label=$(type+'-link-label').value.trim(),raw=$(type+'-link-url').value.trim(),url;try{url=new URL(raw);if(url.protocol!=='http:'&&url.protocol!=='https:')throw new Error()}catch(e){toast('Saisissez une adresse commençant par http:// ou https://');return}if(!id)return;if(state.demo){toast('Disponible dans Grist.');return}await addRecord(TABLES.links,{Parent_Type:type,Parent_Id:id,Label:label||url.hostname,URL:url.href,Notes:'',Created_At:now()});$(type+'-link-label').value='';$(type+'-link-url').value='';await loadData();renderRelated(type,id)}
