var modalStack=[],modalPagePosition=null;
function modalDraft(id){return JSON.stringify(Array.from($(id).querySelectorAll('.grid2 input,.grid2 select,.grid2 textarea')).map(function(el){return [el.id,el.type==='checkbox'?el.checked:el.value]}))}
function showModal(id){
  if(modalStack.some(function(entry){return entry.id===id}))return;
  var previous=modalStack[modalStack.length-1];
  if(previous){previous.scroll=$(previous.id).querySelector('.modal').scrollTop;$(previous.id).classList.add('hidden')}
  else{modalPagePosition={x:window.scrollX,y:window.scrollY,overflow:document.body.style.overflow};document.body.style.overflow='hidden'}
  modalStack.push({id:id,focus:document.activeElement,scroll:0,draft:modalDraft(id)});
  $(id).classList.remove('hidden');$(id).querySelector('.modal').scrollTop=0;
}
function closeModal(id,saved){
  var index=modalStack.findIndex(function(entry){return entry.id===id});
  if(index!==modalStack.length-1||index<0)return;
  if(!saved&&(id==='task-modal'||id==='project-modal')&&modalStack[index].draft!==modalDraft(id)&&!confirm('Quitter cette fiche sans enregistrer les modifications ?'))return;
  var entry=modalStack.pop();$(id).classList.add('hidden');
  if(id==='file-preview-modal'){documentStorage.previewRequest++;$('file-preview-download').onclick=null;$('file-preview-open').onclick=null;$('file-preview-frame').src='about:blank';if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=''}}
  var previous=modalStack[modalStack.length-1];
  if(previous){$(previous.id).classList.remove('hidden');if(previous.id==='project-modal')renderProjectTasks();if(previous.id==='search-modal')renderGlobalSearch();if(previous.id==='dashboard-detail-modal'&&$('project-directory-search'))renderProjectDirectory();$(previous.id).querySelector('.modal').scrollTop=previous.scroll}
  else if(modalPagePosition){document.body.style.overflow=modalPagePosition.overflow;window.scrollTo(modalPagePosition.x,modalPagePosition.y);modalPagePosition=null}
  if(entry.focus&&entry.focus.isConnected)entry.focus.focus({preventScroll:true});
}
function renderProjectTasks(){
  var box=$('project-task-section');if(!box)return;var id=$('project-id').value;box.classList.toggle('hidden',!id);if(!id)return;var taskScroll=$('project-task-list').scrollTop;
  var all=state.tasks.filter(function(t){return String(t.Project_Id)===String(id)}),open=all.filter(function(t){return !isDone(t.Status)});
  $('project-task-count').textContent='Tâches du projet · '+open.length+' ouverte(s)';
  var tasks=all.filter(function(t){return $('project-tasks-done').checked||!isDone(t.Status)}).sort(function(a,b){return Number(isDone(a.Status))-Number(isDone(b.Status))||(Number(a.Due_Date)||Infinity)-(Number(b.Due_Date)||Infinity)||String(a.Title).localeCompare(String(b.Title))});
  $('project-task-list').innerHTML=tasks.length?tasks.map(function(t){return '<div class="project-task-row"><div><strong>'+esc(t.Title)+'</strong><div class="sub">'+esc(taskTypeLabel(t.Type))+' · '+(t.Due_Date?fmtDate(t.Due_Date):'Sans échéance')+'</div></div>'+badge(t.Status)+'<button type="button" class="btn small" onclick="openProjectTask('+t.id+')">Ouvrir</button></div>'}).join(''):'<div class="sub">'+(all.length?'Aucune tâche ouverte. Cochez « Afficher les tâches terminées et annulées » pour consulter les autres.':'Aucune tâche pour ce projet.')+'</div>';$('project-task-list').scrollTop=taskScroll;
}
